/* Shared presentation for new intake, saved cases and current patient / encounter follow-up. */
(()=>{
const drafts=new Map();let latestEpisode=null;
state.antibioticJustifications??={};
const scope=o=>(o.patientId||'NEW-INTAKE')+'|'+(o.encounterId||'device');
function selectionFor(o,preferred){const rows=state.antibioticJustifications[scope(o)]||[],raw=rows.find(x=>x.signature===FNAntibioticSelection.signature(o))||preferred;try{return FNAntibioticSelection.resolve(o,raw||{})}catch{return FNAntibioticSelection.resolve(o,{})}}
function attach(o,preferred){return {...o,selectedJustification:selectionFor(o,preferred)}}
function selectionPanel(o,key){const opt=FNAntibioticSelection.options(o),s=o.selectedJustification;return `<div class="abx-choices" id="abx-choices-${key}"><h3>Choose rationale & supporting evidence</h3><p>Suggestions are not selected automatically. Choose what supports your decision, or write your own rationale. Safety holds remain in force.</p><fieldset><legend>Suggested rationale</legend>${opt.rationale.map(r=>`<label class="abx-choice"><input type="checkbox" data-choice-r="${esc(r.id)}" ${s.rationaleIds.includes(r.id)?'checked':''} onchange="fnAntibioticOrders.choose('${key}')"><span>${esc(r.text)}</span></label>`).join('')}</fieldset><label class="field">Your additional rationale (optional)<textarea data-choice-custom maxlength="600" oninput="fnAntibioticOrders.choose('${key}')">${esc(s.custom)}</textarea></label><fieldset><legend>Supporting evidence · choose applicable sources</legend>${opt.evidence.map(r=>`<label class="abx-choice"><input type="checkbox" data-choice-e="${esc(r.id)}" ${s.evidenceIds.includes(r.id)?'checked':''} onchange="fnAntibioticOrders.choose('${key}')"><span><b>${esc(r.title)}</b> · ${esc(r.version||'dose reference')}<br><small>${esc(r.location||'See linked dosing reference')}</small> <a href="${esc(r.url)}" target="_blank" rel="noopener">Read source</a></span></label>`).join('')}</fieldset><p class="abx-choice-status" role="status">${s.complete?'Selections recorded · review pending':'Choose rationale and corresponding evidence; selections are draft only.'}</p><p class="mini">Saved on this device for these inputs and this patient / encounter. Saving a physician proposal includes the selected evidence in the shared record. Changed findings, regimen or protocol require a fresh selection.</p></div>`}
function persistChoices(){try{localStorage.setItem('fn-demo-v1',JSON.stringify(state));return true}catch{return false}}
function saveChoice(o,s){const key=scope(o),rows=state.antibioticJustifications[key]||[];state.antibioticJustifications[key]=[{signature:s.signature,rationaleIds:s.rationaleIds,evidenceIds:s.evidenceIds,custom:s.custom,recordedAt:new Date().toISOString()},...rows.filter(x=>x.signature!==s.signature)].slice(0,30);return persistChoices()}
function choose(key){const o=drafts.get(key),panel=document.querySelector('#abx-choices-'+key);if(!o||!panel)return;const raw={signature:FNAntibioticSelection.signature(o),rationaleIds:[...panel.querySelectorAll('[data-choice-r]:checked')].map(x=>x.dataset.choiceR),evidenceIds:[...panel.querySelectorAll('[data-choice-e]:checked')].map(x=>x.dataset.choiceE),custom:panel.querySelector('[data-choice-custom]').value};const s=FNAntibioticSelection.resolve(o,raw);o.selectedJustification=s;const saved=saveChoice(o,s);panel.querySelector('.abx-choice-status').textContent=!saved?'Device storage unavailable — export the order set before leaving.':s.complete?'Selections saved · supporting evidence recorded · review pending':'Draft saved · choose rationale and supporting evidence for each selected suggestion.';}
function episodeOrder(d){const prior=d.tasks.some(t=>t.code==='antibiotic'&&t.status==='completed'),input={...d.input,priorAntibiotic:prior?true:d.input.priorAntibiotic};const result={...FNAction.calculate(input,{},0),...d.current,meds:prior?[]:d.current.meds};return attach(FNAntibioticOrders.build(input,result,{patientId:d.patientId,encounterId:window.fnDyn?.snapshot().visitId||'',inputRevision:d.revision,preferredSelection:d.proposal?.evidenceSelection,protocol:d.protocol,formulary:d.protocol.allowedDrugs,priorDoseRecorded:prior,reports:d.tests.map(t=>t.latest)}),d.proposal?.evidenceSelection)}
function summary(o){return FNAntibioticOrders.text(o)+'\n\n'+FNAntibioticSelection.selectedText(o.selectedJustification)}

function render(result,input,context={},key='assessment',compact=false){
 let o;try{o=attach(FNAntibioticOrders.build(input,result,context),context.preferredSelection)}catch{return '<div class="notice" role="alert">Correct invalid assessment inputs before preparing the antibiotic order set.</div>'}drafts.set(key,o);
 const card=m=>`<article class="abx-item"><div class="sectiontitle"><div><small>${esc(m.role)}</small><h3>${esc(m.name)}</h3></div><span class="pill amber">${esc(m.status)}</span></div><dl><dt>Initial dose</dt><dd>${esc(m.initialDose)}</dd><dt>Route / infusion</dt><dd>${esc(m.route)} · ${esc(m.administration)}</dd><dt>Subsequent doses</dt><dd>${esc(m.repeatDose)}</dd><dt>Renal review</dt><dd>${esc(m.renalContext)}</dd><dt>Duration / stop review</dt><dd>${esc(m.duration)}</dd></dl><details ${compact?'':'open'}><summary>Rationale, monitoring & evidence</summary><p>${esc(m.rationale)}</p><p><b>Monitoring:</b> ${esc(m.monitoring)}</p>${m.references.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a></p>`).join('')}</details></article>`;
 return `<section id="abx-${esc(key)}" class="abx-order-set" aria-label="Suggested antibiotic order set"><div class="sectiontitle"><div><span class="intake-eyebrow">URGENT EMPIRICAL ANTIBACTERIAL REVIEW</span><h2>Suggested antibiotic order set</h2></div><span class="pill amber">${esc(o.status)}</span></div><p><b>${esc(o.risk)}</b> · MASCC ${o.mascc??'incomplete'}${o.inputRevision!==null?' · input revision '+o.inputRevision:''}</p><p class="mini">${esc(o.provenance)}${o.protocol?' · '+esc(o.protocol.name)+' v'+esc(o.protocol.version)+' ('+esc(o.protocol.status)+')':''}</p><p>Prepared training draft for prescriber / pharmacy review. Start urgent empirical therapy within 60 minutes of triage when FN is suspected; do not wait for cultures or form completion. No order is signed or sent.</p>${o.holds.length?`<div class="abx-holds" role="note"><b>Resolve before completing this regimen</b><ul>${o.holds.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${o.priorRegimen?`<p><b>Reported ongoing regimen:</b> ${esc(o.priorRegimen)} · Last dose: ${o.lastDoseAt?esc(fmt(o.lastDoseAt)):'verify time'}</p>`:''}${o.items.length?o.items.map(card).join(''):'<p class="notice">No new initial-dose order prepared. Reconcile ongoing treatment or complete the missing findings; clinical treatment must not wait for this draft.</p>'}<details><summary>Companion orders, review & follow-up</summary>${o.care.map(t=>`<p><b>${esc(t.timing)}:</b> ${esc(t.action)}</p>`).join('')}</details><details><summary>Other guideline pathways · alternatives, not additional orders</summary>${o.alternatives.map(t=>`<p><b>${esc(t.name)}</b><br>${esc(t.use)} <a href="${esc(t.ref.url)}" target="_blank" rel="noopener">Evidence</a></p>`).join('')}</details><div class="actions"><button type="button" class="btn" onclick="fnGuidelines.open()">Guidelines & clinical references</button><button type="button" class="btn" onclick="fnAntibioticOrders.full('${esc(key)}')">View complete order-set draft</button><button type="button" class="btn" onclick="fnAntibioticOrders.export('${esc(key)}')">Export order set</button></div><p class="mini">${o.version} · References checked ${o.referenceChecked}. Selection guidance and drug-specific dosing sources are linked separately. Local clinical adoption and validation remain required.</p></section>`;
}
function forEpisode(d,key='episode',compact=false){latestEpisode=d;const prior=d.tasks.some(t=>t.code==='antibiotic'&&t.status==='completed');const input={...d.input,priorAntibiotic:prior?true:d.input.priorAntibiotic};const base=FNAction.calculate(input,{},0),current=d.current;const result={...base,meds:prior?[]:current.meds,alerts:current.alerts,risk:current.risk,missing:current.missing};return render(result,input,{patientId:d.patientId,encounterId:window.fnDyn?.snapshot().visitId||'',inputRevision:d.revision,preferredSelection:d.proposal?.evidenceSelection,protocol:d.protocol,formulary:d.protocol.allowedDrugs,priorDoseRecorded:prior,priorRegimen:d.acceptedPlan?.text||'',reports:d.tests.map(t=>t.latest),provenance:d.triageKnown?'Current saved encounter assessment · verify observation freshness':'Historical / undated source assessment · verify current findings before treatment'},key,compact)}
window.fnAntibioticOrders={render,forEpisode,choose,attach,summary,resetDraft(){delete state.antibioticJustifications['NEW-INTAKE|device'];persistChoices()},linkIntake(pid){const o=drafts.get('intake');if(o&&o.selectedJustification){const next={...o,patientId:pid};saveChoice(next,o.selectedJustification)}},proposal(d){latestEpisode=d;const o=episodeOrder(d),taskChoices=d.tasks.filter(t=>t.justification?.inputRevision===d.revision&&t.justification.signature===FNTaskGuidance.build(d,t).signature);const review=FNTherapyReview.build(d),cultureText=review.reports.map(r=>(r.accession||r.testId)+' ['+r.status+'] '+(r.organism||r.value||'Not identified')+'; AST '+r.astRows.map(x=>x.agent+':'+x.interpretation).join(', ')).join('\n');const baseText=review.positiveReports?['UNSIGNED CULTURE-GUIDED PLAN · '+d.patientId+' · revision '+d.revision,'Current risk: '+d.current.risk,'Original empiric suggestions remain in the episode history and are not repeated as a new initial-dose order.',...review.documentedRegimens.map(x=>'Documented prior therapy: '+x.regimen+' · '+x.at),'Revised medicine(s), dose, route, interval and infusion: prescriber to specify after source / AST / allergy / renal / local protocol review.','Duration, reassessment and source-control plan: prescriber to specify.','No targeted prescription is generated from AST alone.']:null;return (baseText?baseText.join('\n\n'):FNAntibioticOrders.proposal(o))+'\n\nCULTURE-GUIDED REVIEW · '+review.stage+'\n'+review.guidance+(cultureText?'\n'+cultureText:'')+(review.resistanceAlerts.length?'\n'+review.resistanceAlerts.join('\n'):'')+'\nSelect and verify any revised regimen explicitly; no targeted drug or dose is inferred from AST alone.'+(taskChoices.length?'\n\nTASK-SELECTED RATIONALE & EVIDENCE\n'+taskChoices.map(t=>FNTaskGuidance.note(t.justification)).join('\n\n'):'')},selectionPayload(d){const o=episodeOrder(d),s=o.selectedJustification;if(!s.rationaleIds.length&&!s.evidenceIds.length&&!s.custom)return null;FNAntibioticSelection.resolve(o,s,true);return {signature:s.signature,rationaleIds:s.rationaleIds,evidenceIds:s.evidenceIds,custom:s.custom}},fillProposal(){const field=document.querySelector('#dyn-form [name="plan"]');if(field&&latestEpisode)field.value=fnAntibioticOrders.proposal(latestEpisode)},full(key){const o=drafts.get(key);if(!o)return;openDialog('Unsigned antibiotic order-set draft',`<p>Selected justification is separate from the suggested reference rationale and does not approve treatment.</p><pre class="abx-text">${esc(summary(o))}</pre><button class="btn" onclick="closeDialog()">Close</button>`)},export(key){const o=drafts.get(key);if(o)download('FN_antibiotic_order_set_'+(o.patientId||'new_assessment')+'.json',o)},intakeExport(){return drafts.get('intake')||null}};
})();
